<script setup>
import { computed, nextTick, ref } from 'vue';
import { Button, Icon, PageHeader } from '../ui/index.js';
import { WORKSPACE_NAVIGATION } from '../workspace-navigation.js';
import { GUIDE_TOPICS, searchGuide } from './content.js';

const emit=defineEmits(['navigate']);
const query=ref(''),selected=ref('start'),contentHeading=ref(null);
const topic=computed(()=>GUIDE_TOPICS.find(item=>item.id===selected.value));
const searching=computed(()=>!!query.value.trim());
const articles=computed(()=>searchGuide(query.value,selected.value));
const destinations=new Set(WORKSPACE_NAVIGATION.map(([id])=>id));
function openPage(id){if(destinations.has(id)&&id!=='guide')emit('navigate',id);}
async function selectTopic(id){
 selected.value=id;query.value='';await nextTick();
 contentHeading.value?.focus({preventScroll:true});contentHeading.value?.scrollIntoView?.({block:'start'});
}
</script>

<template>
 <div class="system-guide">
  <PageHeader title="使用指引" subtitle="从环境配置到结果分析，找到当前操作的下一步。"/>
  <section class="guide-intro surface" aria-label="查找使用说明">
   <div class="guide-intro-heading"><span class="guide-book"><Icon name="book" :size="24"/></span><div><h2>你好，从这里开始</h2><p>第一次使用先看快速上手；遇到问题时，也可以直接搜索。</p></div></div>
   <div class="guide-search"><Icon name="search" :size="19"/><input v-model="query" type="search" aria-label="搜索使用指引" aria-describedby="guide-search-hint" placeholder="搜索功能或问题，例如：环境变量、长连接、报告" maxlength="200"/><button v-if="query" type="button" aria-label="清空搜索" @click="query=''">清空搜索</button><span id="guide-search-hint" class="guide-search-hint">输入即搜索</span></div>
   <div class="guide-keywords"><span>常用关键词</span><button v-for="keyword in ['环境变量','WebSocket','数据集','JVM','插件']" :key="keyword" type="button" @click="query=keyword">{{ keyword }}</button></div>
  </section>
  <div class="guide-layout" :class="{'is-searching':searching}">
   <aside class="guide-index surface"><p>使用手册</p><nav aria-label="指引主题"><button v-for="item in GUIDE_TOPICS" :key="item.id" type="button" :aria-current="!searching&&selected===item.id?'true':undefined" @click="selectTopic(item.id)"><Icon :name="item.icon" :size="17"/><span>{{ item.title }}</span><Icon name="right" :size="14"/></button></nav><div class="guide-index-note"><Icon name="info" :size="16"/><span>操作指引随系统版本更新，具体选项以对应页面为准。</span></div></aside>
   <section class="guide-content" aria-label="指引内容">
    <header class="guide-content-heading"><div><span class="guide-eyebrow">{{ searching?'查找说明':'PRESSURECOOKER / 使用手册' }}</span><h2 ref="contentHeading" tabindex="-1">{{ searching?'搜索结果':topic.title }}</h2><p v-if="!searching">{{ topic.description }}</p><p v-else role="status" aria-live="polite">找到 {{ articles.length }} 条相关指引</p></div><span class="guide-count">{{ searching?articles.length:topic.articles.length }} 条指引</span></header>
    <div v-if="!articles.length" class="guide-no-results surface"><Icon name="search" :size="30"/><h3>没有找到相关指引</h3><p>试试功能名称或更短的关键词，也可以选择左侧主题。</p><Button @click="query=''">清空搜索</Button></div>
    <div v-else class="guide-articles" :class="{'guide-start':!searching&&selected==='start'}">
     <component :is="article.faq?'details':'article'" v-for="(article,index) in articles" :key="article.id" class="guide-article surface" :class="{'guide-faq':article.faq}" :data-guide-article="article.id" :open="article.faq&&searching?true:undefined">
      <component :is="article.faq?'summary':'header'" class="guide-article-heading"><span v-if="!searching&&selected==='start'" class="guide-step">{{ String(index+1).padStart(2,'0') }}</span><span v-else-if="searching" class="guide-result-topic">{{ article.topicTitle }}</span><h3>{{ article.title }}</h3><Icon v-if="article.faq" name="down" :size="16"/></component>
      <div class="guide-article-body"><p v-if="article.text">{{ article.text }}</p><ol v-if="article.steps"><li v-for="step in article.steps" :key="step">{{ step }}</li></ol><pre v-if="article.example" aria-label="配置示例"><code>{{ article.example }}</code></pre><div v-if="article.note" class="guide-note"><Icon name="info" :size="16"/><p>{{ article.note }}</p></div><button v-if="article.destination" type="button" class="guide-destination" @click="openPage(article.destination)">{{ article.action }}<Icon name="right" :size="15"/></button></div>
     </component>
    </div>
    <footer class="guide-footer"><Icon name="check" :size="15"/><span>这里的跳转只打开对应页面；创建、保存和执行仍由原页面操作。</span></footer>
   </section>
  </div>
 </div>
</template>

