ent);outline-offset:3px}@media(min-width:1800px){.guide-layout{grid-template-columns:228px minmax(0,1fr);gap:32px}.guide-article{padding:25px 28px}}@media(max-width:1100px){.guide-layout{grid-template-columns:180px minmax(0,1fr);gap:18px}.guide-start{grid-template-columns:minmax(0,1fr)}.guide-intro{padding:21px}.guide-article{padding:20px}}@media(max-width:760px){.guide-layout{grid-template-columns:minmax(0,1fr);gap:21px}.guide-index{position:static;padding:12px}.guide-index>p,.guide-index-note{display:none}.guide-index nav{display:flex;flex-wrap:wrap;gap:6px}.guide-index nav button{width:auto;padding:8px 10px;font-size:11px;gap:6px}.guide-index nav button>svg:last-child{display:none}.guide-index nav button>svg:first-child{width:14px;height:14px}.guide-intro{padding:18px;margin-bottom:16px}.guide-intro-heading{gap:10px}.guide-intro h2{font-size:15px}.guide-intro p{font-size:11px}.guide-book{width:38px;height:38px}.guide-search{padding:0 10px;gap:8px}.system-guide .guide-search input{font-size:12px;padding:12px 0}.guide-search-hint,.guide-layout.is-searching .guide-index{display:none}.guide-content-heading h2{font-size:21px}.guide-article{padding:19px 17px}.guide-count{font-size:9px}.guide-content-heading p{font-size:11px}.guide-article h3{font-size:13px}.guide-footer{font-size:10px}}
